class Observable:
    def __init__(self):
        self._observers = []
    def subscribe(self, observer):
        self._observers.append(observer)
    def notify(self, event):
        for observer in self._observers:
            observer(event)

class Order(Observable):
    @status.setter
    def status(self, value):
        old = self._status
        self._status = value
        self.notify({'old': old, 'new': value})

